{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "DingTalk Document JSONML Body Schema",
  "description": "钉钉文档 body JSONML 的结构校验 schema",
  "type": "array",
  "items": { "$ref": "#/definitions/blockNode" },
  "definitions": {
    "blockNode": {
      "oneOf": [
        { "$ref": "#/definitions/paragraph" },
        { "$ref": "#/definitions/heading" },
        { "$ref": "#/definitions/hr" },
        { "$ref": "#/definitions/table" },
        { "$ref": "#/definitions/code" },
        { "$ref": "#/definitions/container" },
        { "$ref": "#/definitions/embed" },
        { "$ref": "#/definitions/onlineVideo" },
        { "$ref": "#/definitions/card" },
        { "$ref": "#/definitions/toc" },
        { "$ref": "#/definitions/refblock" }
      ]
    },
    "inlineContent": {
      "oneOf": [
        { "type": "string" },
        { "$ref": "#/definitions/textNode" },
        { "$ref": "#/definitions/link" },
        { "$ref": "#/definitions/image" },
        { "$ref": "#/definitions/mention" },
        { "$ref": "#/definitions/formula" },
        { "$ref": "#/definitions/sticker" },
        { "$ref": "#/definitions/inlineCode" },
        { "$ref": "#/definitions/br" }
      ]
    },
    "textNode": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": [
        { "type": "string", "const": "text" },
        { "$ref": "#/definitions/textMarks" },
        { "type": "string" }
      ]
    },
    "textMarks": {
      "type": "object",
      "properties": {
        "bold": { "type": "boolean" },
        "italic": { "type": "boolean", "const": true },
        "strike": { "type": "boolean" },
        "dstrike": { "type": "boolean" },
        "underline": {
          "type": "object",
          "properties": {
            "value": { "type": "string", "enum": ["single", "dash", "wave", "double", "none"] },
            "color": { "type": "string" }
          },
          "required": ["value"]
        },
        "color": { "type": "string" },
        "highlight": { "type": "string" },
        "shd": {
          "type": "object",
          "properties": {
            "val": { "type": "string" },
            "color": { "type": "string" },
            "fill": { "type": "string" }
          }
        },
        "sz": { "type": "number" },
        "szUnit": { "type": "string", "enum": ["px", "pt"], "default": "px" },
        "fonts": {
          "type": "object",
          "properties": {
            "ascii": { "type": "string" },
            "hAnsi": { "type": "string" },
            "cs": { "type": "string" },
            "eastAsia": { "type": "string" }
          }
        },
        "vertAlign": { "type": "string", "enum": ["superscript", "subscript", "baseline"] },
        "spacing": { "type": "number", "description": "字间距，单位 pt" }
      },
      "additionalProperties": false
    },
    "paragraphAttrs": {
      "type": "object",
      "properties": {
        "jc": { "type": "string", "enum": ["left", "center", "right", "both", "distribute", "justify"] },
