// 必须先加载crypto-js
var CryptoJs = require("crypto-js");

// 加载补环境（包含mnsv2函数）

// 静默 console 以避免干扰 execjs
var console = {
    log: function() {},
    warn: function() {},
    error: function() {},
    info: function() {},
    debug: function() {}
};

// 代理逻辑（简化版，确保稳定性）
function watch(obj, name) {
    return new Proxy(obj, {
        get(target, prop, receiver) {
            let val = Reflect.get(target, prop, receiver);
            if (val === undefined) {
                // 只有脚本访问了不存在的属性时才打印，减少日志噪音
                console.log(`[Proxy] 访问了空属性: ${name}.${String(prop)}`);
            }
            return val;
        },
        set(target, prop, value) {
            console.log(`[Proxy] 设置属性: ${name}.${String(prop)} = ${value}`);
            return Reflect.set(target, prop, value);
        }
    });
}

function obj_toString(obj, name) {
  Object.defineProperty(obj, Symbol.toStringTag, {
    value: name,
  });
}

